import subprocess,re
files=subprocess.check_output(['git','diff','--name-only','--','.skilled/skills/system-deep-loop/deep-research']).decode().split()
def blocks(t):
    return re.findall(r'^```.*?^```', t, re.S|re.M)
def fm(t):
    m=re.match(r'^---\n.*?\n---\n',t,re.S)
    return m.group(0) if m else ''
for f in files:
    old=subprocess.check_output(['git','show','HEAD:'+f]).decode()
    new=open(f).read()
    bo,bn=blocks(old),blocks(new)
    print(f.split('deep-research/')[-1], 'blocks',len(bo),len(bn),'same' if bo==bn else 'CHANGED', 'fm', 'same' if fm(old)==fm(new) else 'CHANGED')
PY"}

