f='.skilled/skills/system-deep-loop/deep-research/references/protocol/loop-protocol.md'
old=subprocess.check_output(['git','show','HEAD:'+f]).decode().splitlines()
new=open(f).read().splitlines()
def grab(lines, prefix):
    return [l for l in lines if l.startswith(prefix)]
for prefix in ['- `native`','- `cli-opencode`','- `cli-claude-code`','Failure handling']:
    o=grab(old,prefix); n=grab(new,prefix)
    print('###',prefix, len(o),len(n))
    for a,b in zip(o,n):
        sm=difflib.SequenceMatcher(None,a,b)
        print('ratio',round(sm.ratio(),4))
        for tag,i1,i2,j1,j2 in sm.get_opcodes():
            if tag!='equal':
                print(' ',tag,repr(a[i1:i2]),'->',repr(b[j1:j2]))
